      "note": "List any vendor-specific headers beyond standard ones."
    },
    "6_success_criteria": {
      "required": true,
      "http_status_expected": [
        200
      ],
      "response_fields": {
        "field": null,
        "expected_value": null
      },
      "consecutive_successes_required": 3,
